#Region @DOC
#### Description:
#Connects the TM1 database to a Git repository (TM1 Git integration). Wraps the `POST /GitInit` REST API endpoint.
#
#### How to Use:
#
#- `pGitURL`: REQUIRED: the repository URL, e.g. `https://github.com/<owner>/<repo>`.
#- `pDeployment`: OPTIONAL: the deployment name from the `.tm1project` file to use.
#- `pForce`: 1 = replace any existing Git context on the database.
#- `pConnectionName`: a connection name configured in `}bedrock.session.start`, or a connection-details JSON object returned by it. When a JSON object is passed, that session is reused and is not closed at the end of this process.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes.
#
#Credentials, depending on how the repository authenticates:
#- HTTPS: `pUsername` and `pPassword` (for GitHub, use a personal access token as the password).
#- SSH: `pPublicKey` and `pPrivateKey`, plus `pPassphrase` if the key has one.
#
#> [!WARNING]
#> Never save real credentials as parameter defaults. Defaults are stored in the process and exported with it.
#
#### Return Value:
#`sBedrockReturnValue` is set to the response of the `GitInit` request, which describes the Git status.
#
#Here is an example call:
#```
#ExecuteProcess( '}bedrock.git.init',
#  'pConnectionName', 'Development',
#  'pGitURL', 'https://github.com/<owner>/<repo>',
#  'pUsername', '<user>',
#  'pPassword', sToken );
#```
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants
cThisProcName = GetProcessName();
cUserName     = TM1User();
cTimeStamp    = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt    = NumberToString( INT( RAND( ) * 1000000000 ) );
cTemp         = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages     = '{"Process": "'|cThisProcName|'", "User": "'|cUserName|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUserName|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );

pDefaultParameters = '{
  "pConnectionName": "",
  "pGitURL":       "",
  "pDeployment":   "",
  "pUsername":     "",
  "pPassword":     "",
  "pPublicKey":    "",
  "pPrivateKey":   "",
  "pPassphrase":   "",
  "pForce":        0,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pConnectionName": '|StringToJson( pConnectionName )|',
  "pGitURL":       '|StringToJson( pGitURL       )|',
  "pDeployment":   '|StringToJson( pDeployment   )|',
  "pUsername":     '|StringToJson( pUsername      )|',
  "pPassword":     '|StringToJson( pPassword      )|',
  "pPublicKey":    '|StringToJson( pPublicKey     )|',
  "pPrivateKey":   '|StringToJson( pPrivateKey    )|',
  "pPassphrase":   '|StringToJson( pPassphrase    )|',
  "pForce":        '|NumberToString( pForce       )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );

IF( JsonType( JsonGet( pJson, '/pConnectionName' ) ) @= 'string' );
  pConnectionName = JsonToString( pJson, '/pConnectionName' );
ELSE;
  pConnectionName = JsonGet( pJson, '/pConnectionName' );
ENDIF;
pGitURL       = JsonToString( pJson, '/pGitURL'       );
pDeployment   = JsonToString( pJson, '/pDeployment'   );
pUsername     = JsonToString( pJson, '/pUsername'     );
pPassword     = JsonToString( pJson, '/pPassword'     );
pPublicKey    = JsonToString( pJson, '/pPublicKey'    );
pPrivateKey   = JsonToString( pJson, '/pPrivateKey'   );
pPassphrase   = JsonToString( pJson, '/pPassphrase'   );
pForce        = StringToNumber( JsonToString( pJson, '/pForce' ) );
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'Process: ' | cThisProcName | ' | GitURL: ' | pGitURL | ' | Deployment: ' | pDeployment );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

IF( pGitURL @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"pGitURL is required."' );
ENDIF;

#IF( pDeployment @= '' );
#  sMessages = JsonAdd( sMessages, '/Error/0', '"pDeployment is required."' );
#ENDIF;

IF( JsonSize( sMessages, '/Error' ) <> 0 );
  IF( pLogOutput = 1 );
    LogOutput( 'ERROR', 'Validation failed: ' | JsonToString( sMessages, '/Error' ) );
  ENDIF;
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Build Request Body

### Required fields
sBody = '{"URL": ' | StringToJson( pGitURL ) | '}';
sBody = JsonAdd( sBody, 'Force', IF( pForce = 1, 'true', 'false' ) );

### Optional credential fields
IF( pDeployment @<> '' );
  sBody = JsonAdd( sBody, 'Deployment', StringToJson( pDeployment ) );
ENDIF;
IF( pUsername @<> '' );
  sBody = JsonAdd( sBody, 'Username', StringToJson( pUsername ) );
ENDIF;
IF( pPassword @<> '' );
  sBody = JsonAdd( sBody, 'Password', StringToJson( pPassword ) );
ENDIF;
IF( pPublicKey @<> '' );
  sBody = JsonAdd( sBody, 'PublicKey', StringToJson( pPublicKey ) );
ENDIF;
IF( pPrivateKey @<> '' );
  sBody = JsonAdd( sBody, 'PrivateKey', StringToJson( pPrivateKey ) );
ENDIF;
IF( pPassphrase @<> '' );
  sBody = JsonAdd( sBody, 'Passphrase', StringToJson( pPassphrase ) );
ENDIF;

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'GitInit body (credentials redacted): URL=' | pGitURL | ' Deployment=' | pDeployment );
ENDIF;

#EndRegion - Build Request Body
#################################################################################################

#################################################################################################
#Region - Get Connection Details

# Get Database Connection Details
sDatabaseParameterType = JsonType( pConnectionName );
IF( sDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pConnectionName, 'pJson', pJson ); sConnectionDetails = sBedrockReturnValue;
ELSE;
  sConnectionDetails = pConnectionName;
ENDIF;
pJson = JsonAdd( pJson, 'pConnectionName', sConnectionDetails );

sURL        = JsonToString( sConnectionDetails, '/sURL' );
sAuthHeader = JsonToString( sConnectionDetails, '/sAuthHeader' );

### Authentication headers for requests to this connection
sAuthHeaders = '[]';
IF( JsonToString( sConnectionDetails, '/sAuthHeader' ) @<> '' );
  sAuthHeaders = JsonAdd( sAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sConnectionDetails, '/sSID' ) @<> '' );
  sAuthHeaders = JsonAdd( sAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sConnectionDetails, '/sSID' ) ) );
ENDIF;

#EndRegion - Get Connection Details
#################################################################################################

#################################################################################################
#Region - Execute Request

### Conditionally include Authorization header for stateless auth modes
ExecuteProcess( '}bedrock.process.execute_http_request',
  'pMethod',  'POST',
  'pURL',     sURL | '/GitInit',
  'pHeaders', sAuthHeaders,
  'pBody',    sBody,
  'pJson',    pJson
);

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'GitInit complete. Response: ' | sBedrockReturnValue );
ENDIF;

#EndRegion - Execute Request
#################################################################################################

